"""Privacy-utility frontier: trace Rate*(D) = Cov_d(D) for graphs on n
nodes under edge-flip (Hamming) distance."""
from __future__ import annotations
from itertools import combinations, product
from typing import Callable, List, Sequence, Tuple

Graph = Tuple[int, ...]

def all_graphs(n: int) -> List[Graph]:
    m = n * (n - 1) // 2
    return list(product((0, 1), repeat=m))

def hamming(a: Graph, b: Graph) -> int:
    return sum(x != y for x, y in zip(a, b))

def is_cover(states, d, D, centers) -> bool:
    return all(any(d(c, s) <= D for c in centers) for s in states)

def covering_number(states: Sequence[Graph], d: Callable, D: int) -> int:
    for size in range(len(states) + 1):
        for C in combinations(states, size):
            if is_cover(states, d, D, C):
                return size
    return len(states)

if __name__ == "__main__":
    for n in (3, 4):
        S = all_graphs(n)
        maxD = n * (n - 1) // 2
        print(f"n={n} nodes, |S|={len(S)} graphs")
        for D in range(maxD + 1):
            print(f"   D={D}: Rate*(D) = Cov_d(D) = {covering_number(S, hamming, D)}")

