from __future__ import annotations
from itertools import combinations
from typing import Callable, Hashable, Optional, Sequence, Tuple

State = Hashable

def exact_min_cover(states: Sequence[State],
                    d: Callable[[State, State], int],
                    D: int) -> Tuple[int, Optional[Tuple[State, ...]]]:
    """Exact D-covering number (= Rate*(D)) and a witnessing minimum cover,
    by increasing-size brute-force set cover. Suitable for small state spaces."""
    n = len(states)
    for size in range(n + 1):
        for C in combinations(states, size):
            if all(any(d(c, s) <= D for c in C) for s in states):
                return size, C
    return n, tuple(states)

