from __future__ import annotations
from typing import Callable, Dict, Hashable, Sequence, Tuple

State = Hashable

def realise_channel(states: Sequence[State],
                    d: Callable[[State, State], int],
                    D: int,
                    centers: Sequence[State]
                    ) -> Tuple[Callable[[State], State], Callable[[State], State]]:
    """Turn a D-cover into a channel achieving distortion D with rate <= |cover|
    (constructive proof of 'covering implies achieving'): map each state to a
    nearby center; decode by identity."""
    assign: Dict[State, State] = {}
    for s in states:
        assign[s] = next(c for c in centers if d(c, s) <= D)
    return (lambda s: assign[s]), (lambda r: r)

