"""Plot the privacy-utility frontier Rate*(D) = Cov_d(D) for graphs on n
nodes under edge-flip distance."""
import matplotlib.pyplot as plt
from itertools import combinations, product

def all_graphs(n):
    m = n * (n - 1) // 2
    return list(product((0, 1), repeat=m))

def hamming(a, b):
    return sum(x != y for x, y in zip(a, b))

def covering_number(states, D):
    for size in range(len(states) + 1):
        for C in combinations(states, size):
            if all(any(hamming(c, s) <= D for c in C) for s in states):
                return size
    return len(states)

fig, ax = plt.subplots(figsize=(7, 4.5))
for n in (3, 4):
    S = all_graphs(n)
    maxD = n * (n - 1) // 2
    xs = list(range(maxD + 1))
    ys = [covering_number(S, D) for D in xs]
    ax.step(xs, ys, where='post', marker='o', label=f'n={n} nodes (|S|={len(S)})')
