ax.set_ylabel('minimum surveillance rate  Rate*(D)')
ax.set_title('Privacy-Utility Frontier = D-Covering Number')
ax.set_yscale('log', base=2)
ax.legend(); ax.grid(True, alpha=0.3)
plt.tight_layout(); plt.savefig('frontier.png', dpi=150)
